import React, { useEffect, useState, useContext } from "react";
import axios from "axios";
import { AuthContext } from "../context/AuthContext";
import { useNavigate } from "react-router-dom";

export default function AdminDashboard() {
  const { user, token, logout } = useContext(AuthContext);
  const navigate = useNavigate();

  const [votingOpen, setVotingOpen] = useState(false);
  const [pendingUsers, setPendingUsers] = useState([]);
  const [candidates, setCandidates] = useState([]);
  const [logs, setLogs] = useState([]);

  const api = axios.create({
    baseURL: "http://localhost:4000/api/admin",
    headers: { Authorization: `Bearer ${token}` },
  });

  // ----------------------
  // Fetch initial data
  // ----------------------
  useEffect(() => {
    fetchVotingState();
    fetchPendingUsers();
    fetchCandidates();
    fetchLogs();
  }, []);

  const fetchVotingState = async () => {
    try {
      const res = await api.get("/toggle-voting"); // optional endpoint
      setVotingOpen(res.data.votingOpen);
    } catch (err) {
      console.log("Voting state fetch failed", err);
    }
  };

  const fetchPendingUsers = async () => {
    try {
      const res = await api.get("/pending-users");
      setPendingUsers(res.data);
    } catch (err) {
      console.error(err);
    }
  };

  const fetchCandidates = async () => {
    try {
      const res = await api.get("/candidates");
      setCandidates(res.data);
    } catch (err) {
      console.error(err);
    }
  };

  const fetchLogs = async () => {
    try {
      const res = await api.get("/logs");
      setLogs(res.data);
    } catch (err) {
      console.error(err);
    }
  };

  // ----------------------
  // Logout
  // ----------------------
  const handleLogout = () => {
    logout();
    navigate("/login");
  };

  // ----------------------
  // Toggle voting
  // ----------------------
  const toggleVoting = async () => {
    try {
      const res = await api.post("/toggle-voting");
      setVotingOpen(res.data.votingOpen);
      alert(res.data.message);
      fetchLogs();
    } catch (err) {
      console.error(err);
      alert(err.response?.data?.error || "Failed to toggle voting");
    }
  };

  // ----------------------
  // Approve user
  // ----------------------
  const approveUser = async (id) => {
    try {
      const res = await api.post(`/approve-user/${id}`);
      alert(res.data.message);
      fetchPendingUsers();
      fetchLogs();
    } catch (err) {
      console.error(err);
      alert(err.response?.data?.error || "Failed to approve user");
    }
  };

  // ----------------------
  // Add candidate
  // ----------------------
  const addCandidate = async () => {
    const name = prompt("Candidate name:");
    const position = prompt("Position:");
    const party = prompt("Party (optional):");

    if (!name || !position) return;

    try {
      const res = await api.post("/candidates", { name, position, party });
      alert(res.data.message);
      fetchCandidates();
      fetchLogs();
    } catch (err) {
      console.error(err);
      alert(err.response?.data?.error || "Failed to add candidate");
    }
  };

  // ----------------------
  // Edit candidate
  // ----------------------
  const editCandidate = async (candidate) => {
    const name = prompt("New name:", candidate.name);
    const position = prompt("New position:", candidate.position);
    const party = prompt("New party:", candidate.party);

    try {
      const res = await api.put(`/candidates/${candidate.id}`, {
        name,
        position,
        party,
      });
      alert(res.data.message);
      fetchCandidates();
      fetchLogs();
    } catch (err) {
      console.error(err);
      alert(err.response?.data?.error || "Failed to edit candidate");
    }
  };

  // ----------------------
  // Delete candidate
  // ----------------------
  const deleteCandidate = async (id) => {
    if (!window.confirm("Are you sure you want to delete this candidate?")) return;
    try {
      const res = await api.delete(`/candidates/${id}`);
      alert(res.data.message);
      fetchCandidates();
      fetchLogs();
    } catch (err) {
      console.error(err);
      alert(err.response?.data?.error || "Failed to delete candidate");
    }
  };

  // ----------------------
  // Generate report
  // ----------------------
  const generateReport = async () => {
    try {
      const res = await api.post("/generate-report");
      alert(res.data.message);
      fetchLogs();
    } catch (err) {
      console.error(err);
      alert(err.response?.data?.error || "Failed to generate report");
    }
  };

  return (
    <div className="p-6">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold">iVote Admin Dashboard</h1>
        <button
          onClick={handleLogout}
          className="bg-red-600 text-white px-4 py-2 rounded hover:bg-red-700"
        >
          Logout
        </button>
      </div>

      {/* Voting Control */}
      <div className="mb-6">
        <h2 className="text-xl font-semibold">Voting Status</h2>
        <p>Current Status: {votingOpen ? "Open" : "Closed"}</p>
        <button
          onClick={toggleVoting}
          className="mt-2 bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700"
        >
          {votingOpen ? "Close Voting" : "Open Voting"}
        </button>
      </div>

      {/* Pending Users */}
      <div className="mb-6">
        <h2 className="text-xl font-semibold">Pending Voter Registrations</h2>
        {pendingUsers.length === 0 ? (
          <p>No pending users.</p>
        ) : (
          <ul>
            {pendingUsers.map((user) => (
              <li key={user.id} className="flex justify-between my-1">
                <span>{user.name} ({user.studentNumber})</span>
                <button
                  onClick={() => approveUser(user.id)}
                  className="bg-green-600 text-white px-2 py-1 rounded hover:bg-green-700"
                >
                  Approve
                </button>
              </li>
            ))}
          </ul>
        )}
      </div>

      {/* Candidates */}
      <div className="mb-6">
        <h2 className="text-xl font-semibold">Candidates</h2>
        <table className="w-full border-collapse">
          <thead>
            <tr>
              <th className="border px-2 py-1">Name</th>
              <th className="border px-2 py-1">Position</th>
              <th className="border px-2 py-1">Party</th>
              <th className="border px-2 py-1">Actions</th>
            </tr>
          </thead>
          <tbody>
            {candidates.map((c) => (
              <tr key={c.id}>
                <td className="border px-2 py-1">{c.name}</td>
                <td className="border px-2 py-1">{c.position}</td>
                <td className="border px-2 py-1">{c.party || "-"}</td>
                <td className="border px-2 py-1 space-x-2">
                  <button
                    onClick={() => editCandidate(c)}
                    className="bg-yellow-500 text-white px-2 py-1 rounded hover:bg-yellow-600"
                  >
                    Edit
                  </button>
                  <button
                    onClick={() => deleteCandidate(c.id)}
                    className="bg-red-600 text-white px-2 py-1 rounded hover:bg-red-700"
                  >
                    Delete
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
        <button
          onClick={addCandidate}
          className="mt-2 bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700"
        >
          Add Candidate
        </button>
      </div>

      {/* System Logs */}
      <div className="mb-6">
        <h2 className="text-xl font-semibold">System Logs</h2>
        {logs.length === 0 ? (
          <p>No logs available.</p>
        ) : (
          <ul className="max-h-48 overflow-y-scroll border p-2">
            {logs.map((log) => (
              <li key={log.id}>
                {new Date(log.createdAt).toLocaleString()} - {log.action}
              </li>
            ))}
          </ul>
        )}
      </div>

      {/* Reports */}
      <div className="mb-6">
        <h2 className="text-xl font-semibold">Reports</h2>
        <button
          onClick={generateReport}
          className="bg-purple-600 text-white px-4 py-2 rounded hover:bg-purple-700"
        >
          Generate Report
        </button>
      </div>
    </div>
  );
}
